import java.util.Arrays;

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        int[] sortedA = A.clone();
        int[] sortedASqSum = new int[sortedA.length];

        for (int i = 0; i < sortedA.length; i++) {
            sortedASqSum[i] = (int) Math.pow(sortedA[i], 2);
        }

        int[] count = new int[sortedA.length];
        count[0] = 1;

        for (int i = 1; i < sortedA.length; i++) {
            for (int j = 0; j < i; j++) {
                if (sortedASqSum[i] == sortedASqSum[j] + sortedASqSum[i - j - 1]) {
                    count[i] += count[j];
                }
            }
        }

        return count[sortedA.length - 1];
    }
}
