public static List<String> centerSymmetricNumbers(int n) {
    List<String> numbers = new ArrayList<>();
    char[] digits = new char[n];
    for (int i = 0; i < n; i++) {
        digits[i] = '0';
    }
    int count = 1;
    while (count <= n) {
        String number = new String(digits);
        if (number.compareTo("0") == 0 || number.compareTo("1") == 0) {
            count++;
            continue;
        }
        numbers.add(number);
        digits[0] = Character.forDigit(count, 10);
        count++;
    }
    return numbers;
