package com.example;

public class EnergyUtility {
    /**
     * Calculates the energy of the string, which is defined as the length of the longest non-empty substring containing only one character.
     *
     * @param s The input string.
     * @return The energy of the string.
     */
    public static int calculateEnergy(String s) {
        if (s == null || s.length() < 1) {
            return 0;
        }

        int maxLength = 0, start = 0, end = 0;
        for (int i = 0; i < s.length(); i++) {
            int currentLength = 1, count = 1;
            for (int j = i + 1; j < s.length(); j++) {
                if (s.charAt(i) == s.charAt(j)) {
                    count++;
                } else {
                    break;
                }
            }
            if (count > maxLength) {
                maxLength = count;
                start = i;
                end = i + count - 1;
            }
        }

        return end - start + 1;
    }

    public static void main(String[] args) {
        System.out.println(calculateEnergy("")); // Output: 0
        System.out.println(calculateEnergy("a")); // Output: 1
        System.out.println(calculateEnergy("aa")); // Output: 2
        System.out.println(calculateEnergy("abb")); // Output: 2
        System.out.println(calculateEnergy("aabbccdd")); // Output: 2
        System.out.println(calculateEnergy("aaaaaaa")); // Output: 7
        System.out.println(calculateEnergy("abcdefghijklmnopqrstuvwxyz")); // Output: 26
        System.out.println(calculateEnergy("ABCDEFGHIJKLMNOPQRSTUVWXYZ")); // Output: 26
        System.out.println(calculateEnergy("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")); // Output: 52
        System.out.println(calculateEnergy("1234567890")); // Output: 1
    }
}

